def blueprint(name,parent=unreal.Actor):
 f=unreal.BlueprintFactory();f.set_editor_property('parent_class',parent);bp=unreal.load_asset(folder+'/'+name) or T.create_asset(name,folder,unreal.Blueprint,f);assert E.compile_blueprint(bp);return bp

def component(bp,name,cls,mesh=None,collision=True):
 hs=ss.k2_gather_subobject_data_for_blueprint(bp);h=next((h for h in hs if str(lib.get_variable_name(lib.get_data(h)))==name),None)
 if not h:
  h,reason=ss.add_new_subobject(unreal.AddNewSubobjectParams(parent_handle=hs[0],new_class=cls,blueprint_context=bp));assert not str(reason);ss.rename_subobject(h,unreal.Text(name))
 o=lib.get_object_for_blueprint(lib.get_data(h),bp)
 if mesh:o.set_static_mesh(unreal.load_asset(folder+'/Geometry/'+mesh));o.set_collision_profile_name('BlockAll' if collision else 'NoCollision');o.set_editor_property('can_ever_affect_navigation',collision)
 return o

def build(bp,g,name,params=None,pure=False):
 spec={'nodes':g.nodes,'links':g.links,'variables':g.variables}
 if params is not None:spec.update(parameters=params,pure=pure,const=pure)
 assert unreal.DeliveryEditorLibrary.build_logic_graph(bp,name,json.dumps(spec)),name

def op(g,n,fn,a=None,b=None,**kw):
 g.call(n,fn,M,**kw)
 if a:g.link(*a,n,'A')
 if b:g.link(*b,n,'B')
 return(n,'ReturnValue')

